-- DC: 100 researched stops.
--
-- 100 new, 0 updating a row already in the index.
-- After running this and scripts/refresh-site.mts, /explore should read
-- 6667.
--
-- Coordinates are deliberately NOT updated on conflict: a checked position
-- must never be replaced by an unchecked one. Where the existing row came
-- from the OpenStreetMap scan and is wrong by a kilometre, delete that slug
-- first and let this insert instead.
--
-- state is deliberately NOT updated either. That is how an overwritten stop
-- in another state keeps its old state and hides — so the collision check
-- above refuses rather than relying on anyone noticing afterwards.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, timezone)
values
  ('Franciscan Monastery Catacombs', 'franciscan-monastery-catacombs', 'roadside-oddities', 38.93755, -76.98455, 'Washington', 'DC', 'Beneath the Franciscan Monastery are reconstructed Holy Land shrines and catacomb-like passages that make this one of D.C.''s strangest underground religious spaces.', 'limited', 'https://myfranciscan.org/visit/', 'America/New_York'),
  ('International Spy Museum', 'international-spy-museum', 'museums', 38.88387, -77.02546, 'Washington', 'DC', 'A museum built around real espionage tradecraft, disguises, surveillance devices, covert operations, and intelligence history.', 'open', 'https://www.spymuseum.org/', 'America/New_York'),
  ('The Mansion on O Street', 'the-mansion-on-o-street', 'roadside-oddities', 38.9084, -77.04575, 'Washington', 'DC', 'A maze-like mansion filled with secret doors, hidden rooms, themed spaces, memorabilia, and deliberately confusing passageways.', 'limited', 'https://www.omansion.com/', 'America/New_York'),
  ('The Exorcist Stairs', 'the-exorcist-stairs', 'weird-history', 38.90548, -77.07018, 'Washington', 'DC', 'The steep Georgetown staircase made famous by the climax of The Exorcist remains a public pedestrian route and cult-film pilgrimage stop.', 'open', 'https://www.nps.gov/places/capital-traction-company-union-station-exorcist-steps.htm', 'America/New_York'),
  ('National Capitol Columns', 'national-capitol-columns', 'weird-history', 38.9104, -76.96756, 'Washington', 'DC', 'Twenty-two sandstone columns removed from the U.S. Capitol now stand in an open meadow at the National Arboretum like an abandoned classical ruin.', 'open', 'https://www.usna.usda.gov/discover/gardens-collections/national-capitol-columns/', 'America/New_York'),
  ('National Bonsai & Penjing Museum', 'national-bonsai-penjing-museum', 'museums', 38.91202, -76.96871, 'Washington', 'DC', 'The National Arboretum houses a museum-sized collection of miniature trees, including historically significant bonsai and penjing specimens.', 'open', 'https://www.bonsai-nbf.org/', 'America/New_York'),
  ('Culture House', 'culture-house', 'roadside-oddities', 38.88044, -77.01197, 'Washington', 'DC', 'A former church covered in large-scale murals and used as an arts venue, making it one of the most visually unusual buildings in Southwest D.C.', 'open', 'https://www.culturehousedc.org/', 'America/New_York'),
  ('Heurich House Museum', 'heurich-house-museum', 'weird-history', 38.90805, -77.0445, 'Washington', 'DC', 'The preserved Richardsonian mansion of brewer Christian Heurich is packed with original interiors, brewing history, and turn-of-the-century details.', 'limited', 'https://heurichhouse.org/', 'America/New_York'),
  ('Riggs Library', 'riggs-library', 'weird-history', 38.90728, -77.07272, 'Washington', 'DC', 'Georgetown University''s ornate 19th-century Riggs Library survives as a dramatic cast-iron reading room inside Healy Hall; access is generally tied to campus events or special arrangements.', 'limited', 'https://library.georgetown.edu/', 'America/New_York'),
  ('Space Window at Washington National Cathedral', 'space-window-at-washington-national-cathedral', 'roadside-oddities', 38.93112, -77.07163, 'Washington', 'DC', 'A stained-glass window in the National Cathedral contains an actual piece of lunar rock brought back by Apollo 11.', 'open', 'https://cathedral.org/discover/art-architecture/the-space-window/', 'America/New_York'),
  ('Washington Mini Monument', 'washington-mini-monument', 'roadside-oddities', 38.8891, -77.03525, 'Washington', 'DC', 'Near the full-size Washington Monument is a much smaller survey marker that looks like a tiny stone version of the famous obelisk.', 'open', 'https://www.atlasobscura.com/places/washington-mini-monument', 'America/New_York'),
  ('FBI Spy House', 'fbi-spy-house', 'weird-history', 38.92424, -77.0728, 'Washington', 'DC', 'A Georgetown house associated with FBI surveillance of Soviet espionage activity can be viewed from public space; do not enter or disturb the residence.', 'roadside', 'https://www.atlasobscura.com/places/fbi-spy-house', 'America/New_York'),
  ('Lincoln Memorial Undercroft', 'lincoln-memorial-undercroft', 'weird-history', 38.88913, -77.04984, 'Washington', 'DC', 'The enormous support structure beneath the Lincoln Memorial opened for public visitation in 2026, exposing the monument''s cavernous concrete undercroft.', 'limited', 'https://www.nps.gov/linc/planyourvisit/undercroftvisit.htm', 'America/New_York'),
  ('Kenilworth Aquatic Gardens', 'kenilworth-aquatic-gardens', 'roadside-oddities', 38.91278, -76.94333, 'Washington', 'DC', 'A surviving tidal-marsh landscape and historic water-garden complex filled with lotus and water lilies inside the city limits.', 'open', 'https://www.nps.gov/keaq/', 'America/New_York'),
  ('National Building Museum', 'national-building-museum', 'roadside-oddities', 38.8978, -77.01752, 'Washington', 'DC', 'Its colossal Great Hall and giant Corinthian columns make the former Pension Building itself as unusual as the architecture exhibits inside.', 'open', 'https://www.nbm.org/', 'America/New_York'),
  ('Lincoln Book Tower', 'lincoln-book-tower', 'roadside-oddities', 38.89677, -77.02629, 'Washington', 'DC', 'At Ford''s Theatre Center for Education and Leadership, a spiraling tower of thousands of books symbolizes the enormous literature written about Abraham Lincoln.', 'open', 'https://fords.org/', 'America/New_York'),
  ('Zero Milestone', 'zero-milestone', 'roadside-oddities', 38.89511, -77.03657, 'Washington', 'DC', 'This small stone marker south of the White House was intended as the national point from which U.S. road distances would be measured.', 'open', 'https://www.nps.gov/places/000/zero-milestone.htm', 'America/New_York'),
  ('Old Patent Model Museum Collection', 'old-patent-model-museum-collection', 'museums', 38.8981, -77.02253, 'Washington', 'DC', 'Smithsonian collections preserve the strange miniature working models once submitted by inventors seeking U.S. patents.', 'open', 'https://americanhistory.si.edu/', 'America/New_York'),
  ('Secret White House Entrance Route', 'secret-white-house-entrance-route', 'roadside-oddities', 38.9001, -77.03464, 'Washington', 'DC', 'A discreet service and security approach near the White House hints at the enclosed passages and controlled routes used behind the public-facing complex; observe only from lawful public space.', 'roadside', 'https://www.whitehousehistory.org/', 'America/New_York'),
  ('U.S. Capitol Summerhouse', 'us-capitol-summerhouse', 'roadside-oddities', 38.89145, -77.01063, 'Washington', 'DC', 'Frederick Law Olmsted''s red-brick grotto-like Summerhouse provides a surprisingly secluded fountain retreat on the Capitol grounds.', 'open', 'https://www.aoc.gov/explore-capitol-campus/grounds/summerhouse', 'America/New_York'),
  ('Foundry Branch Trolley Trestle Ruins', 'foundry-branch-trolley-trestle-ruins', 'weird-history', 38.90676, -77.07922, 'Washington', 'DC', 'Stone and steel remnants of an old trolley route survive along the edge of Glover Archbold Park as a piece of abandoned transit infrastructure.', 'open', 'https://www.atlasobscura.com/places/foundry-branch-trolley-trestle', 'America/New_York'),
  ('Dumbarton Oaks', 'dumbarton-oaks', 'weird-history', 38.91418, -77.06387, 'Washington', 'DC', 'This Georgetown estate combines Byzantine and Pre-Columbian collections with terraced gardens, hidden paths, and architectural surprises.', 'limited', 'https://www.doaks.org/', 'America/New_York'),
  ('The Peacock Room', 'the-peacock-room', 'roadside-oddities', 38.88798, -77.02645, 'Washington', 'DC', 'James McNeill Whistler''s intensely decorated Peacock Room is a room-sized artwork filled with blue-green ornament and gilded peacocks.', 'open', 'https://asia.si.edu/', 'America/New_York'),
  ('Tudor Place', 'tudor-place', 'weird-history', 38.91149, -77.0629, 'Washington', 'DC', 'A Georgetown estate tied to descendants of Martha Washington preserves unusual family collections, domestic spaces, and nearly two centuries of layered history.', 'limited', 'https://tudorplace.org/', 'America/New_York'),
  ('Barbie Pond on Avenue Q', 'barbie-pond-on-avenue-q', 'roadside-oddities', 38.91087, -77.03408, 'Washington', 'DC', 'An ever-changing front-yard installation stages dolls in elaborate seasonal scenes that have become a neighborhood landmark.', 'roadside', 'https://www.atlasobscura.com/places/barbie-pond-on-avenue-q', 'America/New_York'),
  ('Mount Zion Cemetery Underground Railroad Shelter', 'mount-zion-cemetery-underground-railroad-shelter', 'weird-history', 38.91114, -77.05407, 'Washington', 'DC', 'The Mount Zion–Female Union Band cemetery complex includes a small burial vault traditionally associated with refuge for freedom seekers; visit respectfully during allowed hours.', 'limited', 'https://www.mtzion-fubs.org/', 'America/New_York'),
  ('East Potomac Park Mini Golf', 'east-potomac-park-mini-golf', 'weird-history', 38.87458, -77.0263, 'Washington', 'DC', 'This 1931 miniature-golf course is among the oldest continuously operating miniature-golf courses in the United States.', 'open', 'https://www.playdcgolf.com/', 'America/New_York'),
  ('Titanic Memorial', 'titanic-memorial', 'weird-history', 38.87196, -77.01933, 'Washington', 'DC', 'A waterfront memorial erected by women commemorates men who died while helping women and children escape the Titanic.', 'open', 'https://www.nps.gov/places/000/titanic-memorial.htm', 'America/New_York'),
  ('Albert Einstein Memorial', 'albert-einstein-memorial', 'weird-history', 38.8924, -77.04845, 'Washington', 'DC', 'A monumental bronze Einstein sits with manuscript papers in hand beside a star map embedded in the plaza.', 'open', 'https://www.nasonline.org/about-nas/visiting-nas/einstein-memorial/', 'America/New_York'),
  ('Maine Avenue Fish Market', 'maine-avenue-fish-market', 'weird-history', 38.88096, -77.02833, 'Washington', 'DC', 'D.C.''s historic open-air fish market traces its lineage to the early 1800s and remains an unusual surviving piece of the city''s working waterfront.', 'open', 'https://www.wharfdc.com/fish-market/', 'America/New_York'),
  ('McMillan Sand Filtration Site Ruins', 'mcmillan-sand-filtration-site-ruins', 'weird-history', 38.92463, -77.01059, 'Washington', 'DC', 'Rows of underground filtration cells and surviving waterworks structures preserve the eerie industrial landscape of D.C.''s former McMillan filtration plant; stay in authorized public areas.', 'roadside', 'https://www.atlasobscura.com/places/mcmillan-sand-filtration-site', 'America/New_York'),
  ('Kilroy Was Here at the WWII Memorial', 'kilroy-was-here-at-the-wwii-memorial', 'roadside-oddities', 38.88952, -77.04097, 'Washington', 'DC', 'Two small ''Kilroy Was Here'' engravings hide within the World War II Memorial as nods to one of the war''s most famous pieces of soldier graffiti.', 'open', 'https://www.nps.gov/wwii/', 'America/New_York'),
  ('Renwick Gallery', 'renwick-gallery', 'museums', 38.89912, -77.04127, 'Washington', 'DC', 'The Smithsonian''s Renwick Gallery specializes in American craft and often fills its historic building with immersive and unconventional installations.', 'open', 'https://americanart.si.edu/visit/renwick', 'America/New_York'),
  ('Theodore Roosevelt Island', 'theodore-roosevelt-island', 'roadside-oddities', 38.89273, -77.06139, 'Washington', 'DC', 'A wooded island in the Potomac hides monumental stone tablets and a large Roosevelt statue at the center of an intentionally wild memorial landscape.', 'open', 'https://www.nps.gov/this/', 'America/New_York'),
  ('Library of Congress Card Catalog', 'library-of-congress-card-catalog', 'roadside-oddities', 38.88674, -77.00424, 'Washington', 'DC', 'Millions of physical catalog cards survive inside the Library of Congress as a monumental pre-digital information system; public access varies by area and tour.', 'limited', 'https://www.loc.gov/visit/', 'America/New_York'),
  ('Starship Enterprise NCC-1701 Studio Model', 'starship-enterprise-ncc-1701-studio-model', 'museums', 38.88813, -77.01985, 'Washington', 'DC', 'The original filming model of the USS Enterprise from Star Trek is preserved by the Smithsonian as a major artifact of television and science-fiction history.', 'open', 'https://airandspace.si.edu/', 'America/New_York'),
  ('Folger Shakespeare Library Reading Room', 'folger-shakespeare-library-reading-room', 'museums', 38.88937, -77.00276, 'Washington', 'DC', 'The Folger''s Tudor-inspired reading spaces sit above one of the world''s great Shakespeare collections; some areas require tours, programs, or researcher access.', 'limited', 'https://www.folger.edu/visit/', 'America/New_York'),
  ('St. Elizabeths Hospital Historic Campus', 'st-elizabeths-hospital-historic-campus', 'weird-history', 38.84414, -76.99166, 'Washington', 'DC', 'The landmark psychiatric-hospital campus carries layers of medical, Civil War, and institutional history; many portions remain controlled or restricted, so view only from authorized public areas.', 'roadside', 'https://www.atlasobscura.com/places/st-elizabeths-hospital', 'America/New_York'),
  ('Cedar Hill — Frederick Douglass National Historic Site', 'cedar-hill-frederick-douglass-national-historic-site', 'weird-history', 38.86333, -76.98519, 'Washington', 'DC', 'Frederick Douglass''s hilltop home preserves his rooms, belongings, and commanding view over Washington.', 'limited', 'https://www.nps.gov/frdo/', 'America/New_York'),
  ('Sergeant Stubby', 'sergeant-stubby', 'weird-history', 38.89127, -77.02963, 'Washington', 'DC', 'The preserved remains of Sergeant Stubby, the decorated World War I dog, are part of the Smithsonian''s military-history collections; verify current display status before visiting.', 'limited', 'https://americanhistory.si.edu/', 'America/New_York'),
  ('Fort DeRussy', 'fort-derussy', 'weird-history', 38.96344, -77.05063, 'Washington', 'DC', 'Earthworks from one of Washington''s Civil War defenses survive in Rock Creek Park, reclaimed by woods and trails.', 'open', 'https://www.nps.gov/rocr/learn/historyculture/civil-war-defenses-of-washington.htm', 'America/New_York'),
  ('Holt House', 'holt-house', 'weird-history', 38.92513, -77.04706, 'Washington', 'DC', 'One of Washington''s older surviving country houses stands within the National Zoo landscape and is generally not open as a conventional museum; view from permitted public areas.', 'roadside', 'https://www.atlasobscura.com/places/holt-house', 'America/New_York'),
  ('Basilica of the National Shrine of the Immaculate Conception', 'basilica-of-the-national-shrine-of-the-immaculate-conception', 'roadside-oddities', 38.93346, -77.00073, 'Washington', 'DC', 'The enormous basilica contains dozens of chapels, domes, mosaics, crypt-level spaces, and stylistic variations under one roof.', 'open', 'https://www.nationalshrine.org/', 'America/New_York'),
  ('Halcyon House', 'halcyon-house', 'weird-history', 38.90575, -77.06809, 'Washington', 'DC', 'This imposing Georgetown mansion has accumulated generations of ghost stories and architectural lore; it is private property, so only view from public space.', 'roadside', 'https://www.atlasobscura.com/places/halcyon-house', 'America/New_York'),
  ('House of the Temple', 'house-of-the-temple', 'roadside-oddities', 38.91369, -77.03604, 'Washington', 'DC', 'The monumental Scottish Rite headquarters combines Egyptian, classical, and Masonic symbolism in one of D.C.''s most imposing esoteric buildings.', 'limited', 'https://scottishrite.org/headquarters/house-of-the-temple/', 'America/New_York'),
  ('Peirce Mill Spy Station', 'peirce-mill-spy-station', 'weird-history', 38.94055, -77.0522, 'Washington', 'DC', 'During World War II, intelligence operations used a concealed radio-monitoring site near Peirce Mill; the landscape can be visited, while any restricted structures should be observed only lawfully.', 'roadside', 'https://www.atlasobscura.com/places/peirce-mill-spy-station', 'America/New_York'),
  ('The Big Chair — Anacostia', 'the-big-chair-anacostia', 'roadside-oddities', 38.8654, -76.98969, 'Washington', 'DC', 'A huge chair in Anacostia continues the neighborhood''s long-running tradition of an oversized furniture landmark.', 'roadside', 'https://www.atlasobscura.com/places/the-big-chair', 'America/New_York'),
  ('Martin''s Tavern Presidential Booths', 'martins-tavern-presidential-booths', 'weird-history', 38.90674, -77.0632, 'Washington', 'DC', 'The Georgetown tavern identifies booths associated with presidents and political figures, including the booth tied to John F. Kennedy''s proposal to Jacqueline Bouvier.', 'open', 'https://www.martinstavern.com/', 'America/New_York'),
  ('Bare-Chested George Washington', 'bare-chested-george-washington', 'roadside-oddities', 38.89134, -77.02994, 'Washington', 'DC', 'Horatio Greenough''s seated George Washington depicts the first president in a toga-like classical pose that startled 19th-century viewers.', 'open', 'https://americanhistory.si.edu/collections/object/nmah_463144', 'America/New_York'),
  ('Grace Hopper''s Computer Bug', 'grace-hoppers-computer-bug', 'museums', 38.92145, -77.06702, 'Washington', 'DC', 'A moth taped into a 1947 computer log became one of computing history''s most famous ''bugs''; the original log is a Smithsonian collection object and may not always be on display.', 'limited', 'https://americanhistory.si.edu/', 'America/New_York'),
  ('Uncle Beazley', 'uncle-beazley', 'roadside-oddities', 38.93193, -77.05244, 'Washington', 'DC', 'A large fiberglass Triceratops created for the 1960s children''s television production The Enormous Egg survives at the National Zoo.', 'open', 'https://nationalzoo.si.edu/', 'America/New_York'),
  ('Mary Surratt Boarding House', 'mary-surratt-boarding-house', 'weird-history', 38.89954, -77.02038, 'Washington', 'DC', 'The former boarding house where conspirators connected to Lincoln''s assassination met survives in Chinatown; the building is privately used, so view from public space.', 'roadside', 'https://www.nps.gov/foth/learn/historyculture/mary-surratt.htm', 'America/New_York'),
  ('Old Stone House', 'old-stone-house', 'weird-history', 38.9057, -77.0603, 'Washington', 'DC', 'The oldest structure on its original foundation in D.C. was once mistakenly promoted as a place where George Washington stayed, helping save it from demolition.', 'limited', 'https://www.nps.gov/places/old-stone-house.htm', 'America/New_York'),
  ('Carnegie Library at Mount Vernon Square', 'carnegie-library-at-mount-vernon-square', 'weird-history', 38.90265, -77.02292, 'Washington', 'DC', 'D.C.''s former central Carnegie Library survives as a Beaux-Arts landmark repurposed for retail, exhibitions, and local history.', 'open', 'https://dchistory.org/', 'America/New_York'),
  ('Perry Belmont House / International Temple of the Order of the Eastern Star', 'perry-belmont-house-international-temple-of-the-order-of-the-eastern-star', 'roadside-oddities', 38.91229, -77.04133, 'Washington', 'DC', 'An ornate Gilded Age mansion became the international headquarters of the Order of the Eastern Star and is filled with ceremonial and architectural detail.', 'limited', 'https://www.atlasobscura.com/places/international-temple-of-the-order-of-the-eastern-star', 'America/New_York'),
  ('Abandoned Drawbridge Control Room', 'abandoned-drawbridge-control-room', 'weird-history', 38.88736, -77.05558, 'Washington', 'DC', 'A disused bridge-control structure survives near the Potomac as a relic of movable-bridge infrastructure; observe only from legal public space.', 'roadside', 'https://www.atlasobscura.com/places/abandoned-drawbridge-control-room', 'America/New_York'),
  ('Holodomor Memorial', 'holodomor-memorial', 'weird-history', 38.89745, -77.00952, 'Washington', 'DC', 'A sculptural wall of wheat commemorates the millions who died in the Soviet-engineered famine in Ukraine known as the Holodomor.', 'open', 'https://www.nps.gov/places/holodomor-memorial.htm', 'America/New_York'),
  ('Adams Memorial', 'adams-memorial', 'weird-history', 38.94736, -77.01028, 'Washington', 'DC', 'Augustus Saint-Gaudens''s hooded bronze figure at Rock Creek Cemetery was commissioned by Henry Adams and is intentionally untitled and enigmatic.', 'limited', 'https://www.nps.gov/places/adams-memorial.htm', 'America/New_York'),
  ('Columbian Cannon Foundry Ruins', 'columbian-cannon-foundry-ruins', 'weird-history', 38.90537, -77.079, 'Washington', 'DC', 'Stone remnants tied to a 19th-century cannon foundry survive near the C&O Canal and Georgetown''s industrial corridor.', 'open', 'https://www.atlasobscura.com/places/columbian-cannon-foundry-ruins', 'America/New_York'),
  ('National Academy of Sciences Building', 'national-academy-of-sciences-building', 'museums', 38.89302, -77.04773, 'Washington', 'DC', 'The Academy''s historic building combines scientific symbolism, murals, and architectural details, with the Einstein Memorial immediately outside.', 'limited', 'https://www.nasonline.org/about-nas/visiting-nas/', 'America/New_York'),
  ('Portrait Monument', 'portrait-monument', 'roadside-oddities', 38.89, -77.009, 'Washington', 'DC', 'The Capitol''s monument to Lucretia Mott, Elizabeth Cady Stanton, and Susan B. Anthony includes a conspicuously unfinished block of marble behind the figures.', 'limited', 'https://www.aoc.gov/explore-capitol-campus/art/portrait-monument', 'America/New_York'),
  ('Watergate Steps', 'watergate-steps', 'weird-history', 38.88925, -77.05261, 'Washington', 'DC', 'Broad stone steps behind the Lincoln Memorial were designed as a ceremonial landing from the Potomac, providing the literal ''water gate'' long before the political scandal.', 'open', 'https://www.nps.gov/nama/', 'America/New_York'),
  ('Martha, the Last Passenger Pigeon', 'martha-the-last-passenger-pigeon', 'museums', 38.89124, -77.02604, 'Washington', 'DC', 'The preserved remains of Martha, the last known passenger pigeon, are held by the Smithsonian and have been displayed as a stark extinction artifact; verify current display status.', 'limited', 'https://naturalhistory.si.edu/research/vertebrate-zoology/birds/collections-overview/martha-last-passenger-pigeon', 'America/New_York'),
  ('NIST Newton Apple Tree', 'nist-newton-apple-tree', 'roadside-oddities', 38.9419, -77.06563, 'Washington', 'DC', 'A clone descended from a clone of Isaac Newton''s famous apple tree grows on the former National Bureau of Standards campus.', 'open', 'https://www.nist.gov/', 'America/New_York'),
  ('Hidden K-9 at the Korean War Veterans Memorial', 'hidden-k-9-at-the-korean-war-veterans-memorial', 'roadside-oddities', 38.88773, -77.04716, 'Washington', 'DC', 'A sharp-eyed visitor can find the image of a German shepherd worked into the memorial''s mural wall among the service scenes.', 'open', 'https://www.nps.gov/kowa/', 'America/New_York'),
  ('Belmont-Paul Women''s Equality National Monument', 'belmont-paul-womens-equality-national-monument', 'weird-history', 38.89232, -77.00377, 'Washington', 'DC', 'This historic house served as National Woman''s Party headquarters and preserves the long campaign for women''s political equality.', 'limited', 'https://www.nps.gov/bepa/', 'America/New_York'),
  ('Smithsonian National Carousel', 'smithsonian-national-carousel', 'roadside-oddities', 38.88915, -77.02461, 'Washington', 'DC', 'The restored carousel on the National Mall returned in 2026 and carries a civil-rights-era connection to the desegregation of amusement facilities in the capital region.', 'open', 'https://www.si.edu/', 'America/New_York'),
  ('Chinatown Barnes Dance', 'chinatown-barnes-dance', 'roadside-oddities', 38.89965, -77.02212, 'Washington', 'DC', 'A pedestrian scramble at 7th and H Streets lets people cross in every direction at once and is decorated with Chinatown-themed street details.', 'open', 'https://www.fhwa.dot.gov/infrastructure/barnes.cfm', 'America/New_York'),
  ('Arizona Avenue Trestle', 'arizona-avenue-trestle', 'weird-history', 38.92451, -77.10725, 'Washington', 'DC', 'This crooked former railroad trestle incorporates recycled bridge spans and now carries a trail over Arizona Avenue.', 'open', 'https://www.atlasobscura.com/places/arizona-avenue-trestle', 'America/New_York'),
  ('Mary''s Garden', 'marys-garden', 'roadside-oddities', 38.9317, -77.00125, 'Washington', 'DC', 'A quiet devotional garden tucked beside the Basilica offers a small, overlooked landscape of Marian sculpture and plantings.', 'open', 'https://www.nationalshrine.org/', 'America/New_York'),
  ('D.C.''s Underground Bald Cypress Fossils', 'dcs-underground-bald-cypress-fossils', 'roadside-oddities', 38.89895, -77.03769, 'Washington', 'DC', 'Fossilized remains of an ancient bald-cypress swamp have been found beneath downtown D.C.; modern bald cypresses in Lafayette Square mark the strange buried landscape.', 'open', 'https://pubs.usgs.gov/', 'America/New_York'),
  ('District of Columbia Center Point', 'district-of-columbia-center-point', 'roadside-oddities', 38.88984, -77.00903, 'Washington', 'DC', 'A small marble compass in the U.S. Capitol Crypt marks the traditional meeting point of D.C.''s four quadrants; it is reached on authorized Capitol visits.', 'limited', 'https://www.aoc.gov/explore-capitol-campus/buildings-grounds/capitol-building/crypt', 'America/New_York'),
  ('Congressional Cemetery', 'congressional-cemetery', 'weird-history', 38.88283, -76.979, 'Washington', 'DC', 'This historic cemetery holds cenotaphs, political figures, artists, activists, and an unusually eclectic collection of monuments and stories.', 'open', 'https://congressionalcemetery.org/', 'America/New_York'),
  ('Capitol Tile Room', 'capitol-tile-room', 'roadside-oddities', 38.88984, -77.00973, 'Washington', 'DC', 'A little-known Capitol storage space preserves ornate leftover floor tiles from 19th-century renovations; access is not part of ordinary public wandering and should be treated as special-access only.', 'limited', 'https://www.atlasobscura.com/places/capitol-tile-room', 'America/New_York'),
  ('Owney the Postal Dog', 'owney-the-postal-dog', 'museums', 38.89807, -77.0082, 'Washington', 'DC', 'The taxidermied mascot of the Railway Mail Service traveled vast distances with postal workers and is now preserved at the National Postal Museum.', 'open', 'https://postalmuseum.si.edu/exhibition/behind-the-badge/owney', 'America/New_York'),
  ('Glenwood Cemetery Chainsaw Sculptures', 'glenwood-cemetery-chainsaw-sculptures', 'weird-history', 38.92307, -77.00648, 'Washington', 'DC', 'Large figures carved from fallen old-growth trees stand behind Glenwood Cemetery''s chapel; observe normal cemetery hours and etiquette.', 'limited', 'https://www.atlasobscura.com/places/glenwood-cemeterys-chainsaw-sculptures', 'America/New_York'),
  ('Throne of the Third Heaven', 'throne-of-the-third-heaven', 'roadside-oddities', 38.89799, -77.02301, 'Washington', 'DC', 'James Hampton''s monumental foil-covered visionary throne was assembled from discarded materials and is now one of the Smithsonian American Art Museum''s signature outsider-art works.', 'open', 'https://americanart.si.edu/artwork/throne-third-heaven-nations-millennium-general-assembly-9897', 'America/New_York'),
  ('Ben''s Chili Bowl Mural', 'bens-chili-bowl-mural', 'roadside-oddities', 38.91724, -77.02881, 'Washington', 'DC', 'The exterior of Ben''s Chili Bowl carries a large mural honoring prominent Black cultural figures, turning a restaurant wall into a public-art destination.', 'roadside', 'https://benschilibowl.com/', 'America/New_York'),
  ('Willard InterContinental Lobby', 'willard-intercontinental-lobby', 'folklore', 38.8966, -77.03227, 'Washington', 'DC', 'The Willard''s lobby is tied to generations of political meetings and the popular, though debated, story connecting Ulysses S. Grant''s visitors with the word ''lobbyist.''', 'open', 'https://washington.intercontinental.com/', 'America/New_York'),
  ('Preamble in License Plates', 'preamble-in-license-plates', 'roadside-oddities', 38.89787, -77.02305, 'Washington', 'DC', 'At the Smithsonian American Art Museum, the Constitution''s preamble is spelled out using vanity license plates.', 'open', 'https://americanart.si.edu/', 'America/New_York'),
  ('Navy Yard Railroad Gun', 'navy-yard-railroad-gun', 'weird-history', 38.8724, -76.99618, 'Washington', 'DC', 'A massive World War I-era naval railway gun survives at the Washington Navy Yard; access is subject to active military security and visitor rules.', 'limited', 'https://www.history.navy.mil/', 'America/New_York'),
  ('Hall of Fake Presidents', 'hall-of-fake-presidents', 'museums', 38.92208, -76.99752, 'Washington', 'DC', 'A movie-theater display celebrates fictional U.S. presidents from film and television rather than the real occupants of the White House.', 'open', 'https://drafthouse.com/dc-metro-area/theater/bryant-street', 'America/New_York'),
  ('Gun Barrel Fence', 'gun-barrel-fence', 'roadside-oddities', 38.90943, -77.0574, 'Washington', 'DC', 'A Georgetown iron fence has long been identified as being made from recycled gun barrels, though the exact origin remains debated.', 'roadside', 'https://www.atlasobscura.com/places/gun-barrel-fence', 'America/New_York'),
  ('The Cairo', 'the-cairo', 'roadside-oddities', 38.91133, -77.03751, 'Washington', 'DC', 'This unusually tall 1890s apartment building helped provoke the backlash that shaped Washington''s later building-height restrictions.', 'roadside', 'https://www.atlasobscura.com/places/the-cairo-washington-dc', 'America/New_York'),
  ('Serenity Statue', 'serenity-statue', 'roadside-oddities', 38.92197, -77.03614, 'Washington', 'DC', 'A small weathered memorial statue in Meridian Hill Park has endured repeated vandalism and repairs, giving it a strange afterlife among D.C. monuments.', 'open', 'https://www.atlasobscura.com/places/serenity-statue', 'America/New_York'),
  ('Capitalsaurus Court', 'capitalsaurus-court', 'weird-history', 38.882, -77.00584, 'Washington', 'DC', 'A small street designation marks the area where dinosaur bones were uncovered in the 19th century, inspiring D.C.''s official dinosaur, Capitalsaurus.', 'roadside', 'https://www.atlasobscura.com/places/capitalsaurus-court', 'America/New_York'),
  ('Daguerre Monument', 'daguerre-monument', 'weird-history', 38.89735, -77.02206, 'Washington', 'DC', 'A monument near the National Portrait Gallery honors Louis Daguerre and the early photographic process that bears his name.', 'open', 'https://www.loc.gov/pictures/item/2001695538/', 'America/New_York'),
  ('Fort Reno Park High Point', 'fort-reno-park-high-point', 'weird-history', 38.95252, -77.07911, 'Washington', 'DC', 'D.C.''s highest natural point sits in Fort Reno Park, near the site of Civil War defenses and later Cold War communications infrastructure.', 'open', 'https://www.nps.gov/cwdw/learn/historyculture/fort-reno.htm', 'America/New_York'),
  ('Historic Elevator at Potbelly', 'historic-elevator-at-potbelly', 'roadside-oddities', 38.89434, -77.02143, 'Washington', 'DC', 'Behind plexiglass inside the Indiana Avenue Potbelly is a 19th-century open-cage elevator, long misidentified as an 1850s Otis but still a genuine antique machine.', 'open', 'https://www.atlasobscura.com/places/potbelly-elevator', 'America/New_York'),
  ('Washington Monument Lightning Rod', 'washington-monument-lightning-rod', 'roadside-oddities', 38.88945, -77.03525, 'Washington', 'DC', 'The Washington Monument''s aluminum apex and later lightning-protection system tell a surprisingly destructive history of repeated lightning strikes high above the Mall.', 'open', 'https://www.nps.gov/wamo/', 'America/New_York'),
  ('Sonny Bono Memorial Park', 'sonny-bono-memorial-park', 'roadside-oddities', 38.90832, -77.04471, 'Washington', 'DC', 'A tiny triangular private memorial park contains a plaque to Sonny Bono and, according to its creator, a buried cache that includes sheet music.', 'open', 'https://www.atlasobscura.com/places/sonny-bono-memorial-park', 'America/New_York'),
  ('Japanese American Memorial to Patriotism During World War II', 'japanese-american-memorial-to-patriotism-during-world-war-ii', 'weird-history', 38.89458, -77.01057, 'Washington', 'DC', 'Bronze cranes tangled in barbed wire anchor a memorial documenting Japanese American incarceration and military service during World War II.', 'open', 'https://www.nps.gov/places/japanese-american-memorial-to-patriotism-during-world-war-ii.htm', 'America/New_York'),
  ('Knife Edge at the National Gallery', 'knife-edge-at-the-national-gallery', 'roadside-oddities', 38.89094, -77.01723, 'Washington', 'DC', 'I. M. Pei''s East Building forms a 19.5-degree marble prow so sharp and tactile that architecture fans have turned the corner into a minor pilgrimage site.', 'open', 'https://www.nga.gov/', 'America/New_York'),
  ('Godey Lime Kilns', 'godey-lime-kilns', 'weird-history', 38.90373, -77.05643, 'Washington', 'DC', 'Two surviving 19th-century lime kilns sit improbably close to Rock Creek and Potomac Parkway, remnants of Georgetown''s industrial past.', 'roadside', 'https://www.loc.gov/pictures/item/dc0327/', 'America/New_York'),
  ('Sharpshooter''s Tree Marker', 'sharpshooters-tree-marker', 'folklore', 38.97363, -77.02785, 'Washington', 'DC', 'A small marker near the former Walter Reed grounds recalls the Confederate sharpshooter said to have fired toward Abraham Lincoln during the Battle of Fort Stevens; access can be controlled.', 'limited', 'https://www.nps.gov/articles/president-lincoln-under-fire-at-fort-stevens.htm', 'America/New_York'),
  ('Washington Coliseum / Uline Arena', 'washington-coliseum-uline-arena', 'weird-history', 38.90537, -77.00238, 'Washington', 'DC', 'The old Uline Arena hosted the Beatles'' first U.S. concert and now survives as a dramatically repurposed commercial building.', 'open', 'https://www.atlasobscura.com/places/washington-coliseum-1', 'America/New_York'),
  ('Washington Monument Marble Stripe', 'washington-monument-marble-stripe', 'roadside-oddities', 38.88953, -77.03514, 'Washington', 'DC', 'A visible change in marble color partway up the Washington Monument records the long interruption between its two major construction phases.', 'open', 'https://www.nps.gov/wamo/', 'America/New_York'),
  ('Old Post Office Tower', 'old-post-office-tower', 'roadside-oddities', 38.89372, -77.02776, 'Washington', 'DC', 'A National Park Service observation tower rises above the Old Post Office and contains the Bells of Congress, with free elevated views over central Washington.', 'open', 'https://www.nps.gov/thingstodo/old-post-office-tower.htm', 'America/New_York'),
  ('National Cathedral Bell Tower', 'national-cathedral-bell-tower', 'roadside-oddities', 38.93059, -77.07065, 'Washington', 'DC', 'Special tower climbs can reach the National Cathedral''s bell room and spaces normally unseen by casual visitors.', 'limited', 'https://cathedral.org/', 'America/New_York'),
  ('Temperance Fountain', 'temperance-fountain', 'roadside-oddities', 38.8938, -77.02166, 'Washington', 'DC', 'A much-mocked 19th-century fountain was donated by a temperance advocate who hoped free drinking water would steer people away from alcohol.', 'open', 'https://www.atlasobscura.com/places/temperance-fountain-of-washington-dc', 'America/New_York')
